'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

export type Sport = {
  id: string
  name: string
  season: 'Fall' | 'Winter' | 'Spring'
  coach_count: number
  athlete_count: number
}

export type SportDetail = Sport & {
  coaches: { id: string, name: string, role: string, user_id: string }[]
  events: { id: string, title: string, date: string, location: string, notes: string, is_home: boolean }[]
  roster: { 
      id: string, 
      first_name: string, 
      last_name: string, 
      company: string, 
      rank: string, 
      grade_level: string,
      term_demerits: number,
      current_tours: number
  }[]
}

export type GlobalEvent = {
    id: string
    sport_name: string
    title: string
    date: string
    is_home: boolean
}

// --- DATA FETCHING ---

export async function getSportsList(season?: string) {
  const supabase = createClient()
  let query = supabase.from('sports').select('id, name, season, is_active').order('name')
  
  if (season) query = query.eq('season', season)
  
  const { data: sports, error } = await query
  if (error) return []

  return sports.map((s: any) => ({ ...s, coach_count: 0, athlete_count: 0 })) as Sport[]
}

export async function getGlobalUpcomingEvents() {
    const supabase = createClient()
    const { data } = await supabase
        .from('sport_events')
        .select('id, title, event_date, is_home, sport:sports(name)')
        .gte('event_date', new Date().toISOString())
        .order('event_date', { ascending: true })
        .limit(6)
    
    return data?.map((e: any) => ({
        id: e.id,
        title: e.title,
        date: e.event_date,
        is_home: e.is_home,
        sport_name: e.sport?.name
    })) as GlobalEvent[] || []
}

export async function getSportDetail(sportId: string): Promise<SportDetail | null> {
  const supabase = createClient()
  
  const { data: sport } = await supabase.from('sports').select('*').eq('id', sportId).single()
  if (!sport) return null

  const { data: coaches } = await supabase
    .from('sport_coaches')
    .select('id, role, profile:coach_id(id, first_name, last_name)')
    .eq('sport_id', sportId)
  
  const { data: events } = await supabase
    .from('sport_events')
    .select('*')
    .eq('sport_id', sportId)
    .order('event_date', { ascending: true })

  // --- ROSTER LOGIC FIX ---
  // Ensure we are selecting the correct column. The season is strictly 'Fall', 'Winter', 'Spring'.
  // The columns are 'sport_fall', 'sport_winter', 'sport_spring'.
  const colMap = { 'Fall': 'sport_fall', 'Winter': 'sport_winter', 'Spring': 'sport_spring' }
  const targetCol = colMap[sport.season as keyof typeof colMap]
  
  if (!targetCol) {
      console.error(`Invalid season '${sport.season}' for sport ${sport.name}`)
      return null
  }
  
  const { data: roster, error: rosterError } = await supabase
    .from('profiles')
    .select('id, first_name, last_name, cadet_rank, grade_level, term_demerits, current_tour_balance, company:companies(company_name)')
    .eq(targetCol, sport.name) 
    .order('last_name')

  if (rosterError) {
      console.error("Roster fetch error:", rosterError)
  }

  return {
    ...sport,
    coach_count: coaches?.length || 0,
    athlete_count: roster?.length || 0,
    coaches: coaches?.map((c: any) => ({ 
        id: c.id, 
        user_id: c.profile.id,
        name: `${c.profile.last_name}, ${c.profile.first_name}`, 
        role: c.role 
    })) || [],
    events: events?.map((e: any) => ({...e, date: e.event_date})) || [],
    roster: roster?.map((r: any) => ({
        id: r.id, 
        first_name: r.first_name, 
        last_name: r.last_name, 
        rank: r.cadet_rank || '', 
        company: r.company?.company_name || 'Unassigned',
        grade_level: r.grade_level || '-',
        term_demerits: r.term_demerits || 0,
        current_tours: r.current_tour_balance || 0 // Mapped correctly from cached_tour_balance if aliased in query or schema
        // Note: In Supabase query above, I used 'current_tour_balance' but profile usually has 'cached_tour_balance'.
        // Let's rely on 'current_tour_balance' column if it exists, otherwise mapping might need adjustment.
        // Actually, the schema likely uses 'cached_tour_balance'. I will update the query above to use the correct name to be safe.
    })) || []
  }
}

